INSERT INTO "library"."health_categories" ("name", "sf_symbol", "color1", "color2", "order", "fda_disclaimer", "intro_content", "long_name") VALUES ('Brain', 'brain.fill', 'FF81A9', 'F76A97', '1', 'These statements have not been evaluated by the Food and Drug Administration. This information is not intended to diagnose, treat, cure, or prevent any disease.', '[{"body":"🧠 Your brain is recalibrating! Each day without THC allows your mind to regain focus, energy, and motivation —  you''ll unlock milestones that show your cognitive recovery along the way!","type":"card","title":"What is this?","sfSymbol":"questionmark.circle.fill"},{"body":"Stopping cannabis lets CB₁ receptors reset, restoring balance in the endocannabinoid system. As they recover, focus, memory, and motivation begin to improve — revealing how adaptable your brain really is.","type":"card","title":"Introduction","sfSymbol":"hand.wave.fill"},{"body":"If you experience severe mood changes, confusion, or persistent cognitive symptoms, please consult a medical professional. This timeline is intended for individuals without preexisting neurological or psychiatric conditions. It reflects general improvements observed in brain function and endocannabinoid balance after reducing or stopping cannabis use, with a focus on supporting mental clarity, focus, and emotional stability.","type":"text","title":"Disclaimer"}]', 'Brain'), ('Heart', 'heart.fill', 'F65555', 'F63E3E', '3', 'These statements have not been evaluated by the Food and Drug Administration. This information is not intended to diagnose, treat, cure, or prevent any disease.', '[{"body":"🫀 Your heart is finding its rhythm again! This page tracks how your cardiovascular system stabilizes and strengthens as you continue your reset!","type":"card","title":"What is this?","sfSymbol":"questionmark.circle.fill"},{"body":"After cannabis use stops, heart rate and blood pressure begin to normalize, circulation improves, and inflammation decreases — reflecting your heart''s return to steady, balanced function.","type":"card","title":"Introduction","sfSymbol":"hand.wave.fill"},{"body":"If you experience chest pain, heart palpitations, or any concerning cardiovascular symptoms, please consult a medical professional. This timeline is intended for individuals without preexisting heart disease or hypertension. It reflects general improvements observed in cardiovascular function after reducing or stopping cannabis use, with a focus on supporting healthy circulation and cardiac recovery.","type":"text","title":"Disclaimer"}]', 'Brain'), ('Lungs', 'lungs.fill', 'FB6C80', 'FB5F75', '2', 'These statements have not been evaluated by the Food and Drug Administration. This information is not intended to diagnose, treat, cure, or prevent any disease.', '[{"body":"🫁 Your lungs are rebuilding their strength! As you give your body time to recover, you''ll unlock achievements showing how your breathing, endurance, and lung function improve with each day!","type":"card","title":"What is this?","sfSymbol":"questionmark.circle.fill"},{"body":"When cannabis use pauses, the lungs clear irritants and reduce inflammation. Cilia regrow, airflow improves, and each breath becomes easier — proof your body is healing itself day by day.","type":"card","title":"Introduction","sfSymbol":"hand.wave.fill"},{"body":"If you are experiencing serious or ongoing breathing problems, please consult a medical professional. This timeline is intended for individuals without preexisting lung disease or damage. It reflects general improvements observed in lung health after quitting cannabis (when smoked), with a focus on preventing future harm and supporting respiratory recovery.","type":"text","title":"Disclaimer"}]', 'Lungs');
INSERT INTO "library"."health_steps" ("id", "category", "days_without_weed", "percentage", "text", "citation", "minute_offset") VALUES ('1', 'Brain', '1', '9', 'THC begins clearing from the brain initiating CB₁ receptor recovery', 'Hirvonen J et al. Mol Psychiatry. 2012;17(6):642–649.', '30'), ('2', 'Brain', '2', '18', 'CB₁ receptor availability begins returning toward baseline', 'Hirvonen J et al. 2012.', '17'), ('3', 'Brain', '4', '28', 'Endocannabinoid signaling strengthens supporting memory and attention', 'Broyd SJ et al. JAMA Psychiatry. 2016;73(7):711–720.', '0'), ('4', 'Brain', '7', '42', 'CB₁ receptor density increases in brain regions linked to attention and motivation', 'Zamberletti E et al. Br J Pharmacol. 2017;174(19):3131–3146.', '78'), ('5', 'Brain', '10', '49', 'Anandamide and 2-AG levels begin stabilizing as the ECS normalizes', 'Cota D et al. J Neuroendocrinol. 2007;19(1):35–53.', '43'), ('6', 'Brain', '14', '55', 'CB₁ receptor recovery continues in the hippocampus a region central to memory and learning', 'Villares J. Neuroscience. 2007;145(1):323–334.', '45'), ('7', 'Brain', '17', '61', 'Stabilized CB₁ signaling supports reduced mental fatigue and better cognitive endurance', 'Ceccarini J et al. Brain Res. 2015;1628:190–197.', '0'), ('8', 'Brain', '21', '75', 'ECS balance improves helping regulate sleep and emotional recovery', 'Vandrey R et al. Drug Alcohol Depend. 2011;117(1):38–44.', '0'), ('9', 'Brain', '26', '82', 'Endocannabinoid system function continues stabilizing supporting emotional regulation and cognitive control', 'Hirvonen J et al. 2012.', '89'), ('10', 'Brain', '30', '87', 'CB₁ receptor availability returns to baseline in most brain regions restoring cognitive and motivational balance', 'Hirvonen J et al. 2012; Volkow ND et al. N Engl J Med. 2014;370:2219–2227.', '39'), ('11', 'Brain', '40', '91', 'CB₁ receptor normalization strengthens across cortical and limbic regions improving communication between brain areas tied to focus and motivation', 'Hirvonen J et al. 2012; Ceccarini J et al. 2015.', '184'), ('12', 'Brain', '50', '93', 'Verbal learning and memory performance show continued improvement following sustained abstinence', 'Schuster RM et al. Exp Clin Psychopharmacol. 2016;24(1):10–22.', '178'), ('13', 'Brain', '60', '96', 'Working memory and executive function approach non-user baselines; frontal cortex activity becomes more efficient during cognitive tasks', 'Battistella G et al. Biol Psychiatry. 2014;75(6):472–481.', '69'), ('14', 'Brain', '75', '98', 'Brain perfusion and neural connectivity patterns normalize; mood and motivation regulation improve alongside stable ECS signaling', 'Filbey FM et al. JAMA Psychiatry. 2014;71(7):818–827.', '-34'), ('15', 'Brain', '90', '100', 'Long-term CB₁ receptor homeostasis achieved. Cognitive emotional and motivational systems function near baseline supporting sustained clarity and balance', 'Hirvonen J et al. 2012; Ceccarini J et al. 2015; Volkow ND et al. 2014.', '83'), ('16', 'Heart', '1', '14', 'Resting heart rate begins decreasing as THC''s stimulating effects wear off', 'Jones RT. J Clin Pharmacol. 2002;42(S1):58S–63S. Vandrey R et al. J Addict Med. 2011;5(1):16–20.', '123'), ('17', 'Heart', '2', '29', 'Blood pressure begins stabilizing after temporary elevation during early withdrawal', 'Vandrey R et al. 2011.', '-34'), ('18', 'Heart', '5', '43', 'Endothelial function begins improving enhancing blood vessel dilation and circulation', 'Rezkalla SH & Kloner RA. Trends Cardiovasc Med. 2019;29(7):403–407. Reddy LV et al. J Clin Med. 2020;9(6):1925.', '0'), ('19', 'Heart', '10', '63', 'Risk factors associated with arrhythmia begin decreasing as autonomic balance normalizes', 'Desai R et al. J Am Coll Cardiol. 2020;75(11):1111.', '125'), ('20', 'Heart', '20', '78', 'Inflammatory markers linked to cannabis use begin declining easing vascular stress', 'Skosnik PD et al. Acta Neuropsychiatr. 2016;28(5):234–241.', '0'), ('21', 'Heart', '30', '88', 'Overall cardiovascular function improves relative to cannabis baseline with steadier heart rate blood pressure and vascular tone', 'Rezkalla SH & Kloner RA 2019; Jones RT 2002.', '92'), ('22', 'Heart', '40', '92', 'Vascular elasticity improves as endothelial function continues to strengthen; circulation efficiency increases', 'Reddy LV et al. 2020; Rezkalla SH & Kloner RA 2019.', '35'), ('23', 'Heart', '50', '94', 'Markers of oxidative stress begin to normalize supporting healthier arterial tone and blood flow', 'Pacher P et al. Am J Physiol Heart Circ Physiol. 2018;314(1):H1–H17.', '-94'), ('24', 'Heart', '60', '95', 'Heart rate variability (HRV) improves indicating balanced autonomic nervous system function', 'Gruber SA et al. Front Psychiatry. 2021;12:619950.', '-69'), ('25', 'Heart', '75', '99', 'Sustained abstinence supports long-term vascular and inflammatory health lowering overall cardiovascular load', 'Pletcher MJ et al. JAMA. 2012;307(2):173–181.', '12'), ('26', 'Heart', '90', '100', 'Circulatory efficiency and cardiac resilience approach baseline; consistent abstinence supports healthy heart rate blood pressure and vessel function', 'Rezkalla SH & Kloner RA 2019; Reddy LV et al. 2020; Pletcher MJ et al. 2012.', '17'), ('27', 'Lungs', '1', '7', 'Carbon monoxide (CO) levels in the blood begin returning to normal improving oxygen delivery to tissues', 'SolutionHealth – A Timeline of What Happens After You Quit Smoking', '0'), ('28', 'Lungs', '3', '19', 'Cilia in the respiratory tract begin regenerating increasing the lungs'' ability to clear mucus and debris', 'Mayo Clinic – Smoking Detox and Lung Recovery', '0'), ('29', 'Lungs', '5', '31', 'Symptoms of chronic bronchitis (cough phlegm wheeze) begin to decrease after quitting cannabis', 'Hancox RJ et al. Effects of quitting cannabis on respiratory symptoms. Eur Respir J. 2015;46(1):80–87.', '242'), ('30', 'Lungs', '7', '39', 'Coughing may temporarily increase as cilia regain function and mucus is actively cleared from the lungs', 'Mayo Clinic – Smoking Detox and Lung Recovery', '0'), ('31', 'Lungs', '10', '52', 'Inflammation in the airways begins to reduce improving lung reactivity and easing irritation', 'Tashkin DP. Effects of marijuana smoking on the lungs. Ann Am Thorac Soc. 2013;10(3):239–247.', '-30'), ('32', 'Lungs', '14', '61', 'Lung function indicators (e.g. FEV₁ and FVC) begin to measurably improve', 'Hancox RJ et al. Eur Respir J. 2015.', '0'), ('33', 'Lungs', '18', '74', 'Small airway resistance continues to decline improving airflow efficiency', 'Tashkin DP. Ann Am Thorac Soc. 2013.', '0'), ('34', 'Lungs', '22', '81', 'Respiratory endurance and airflow continue to improve as inflammation and mucus buildup decline', 'Supported by Hancox RJ et al. 2015 and Tashkin DP 2013.', '0'), ('35', 'Lungs', '26', '86', 'Airways continue stabilizing as inflammation remains low and cilia function strengthens', 'Healthline – Lung Function After Quitting Smoking', '0'), ('36', 'Lungs', '30', '91', 'Early recovery phase complete; lungs are defending themselves more efficiently with reduced irritation and restored airflow', 'Hancox RJ et al. 2015; Tashkin DP 2013.', '12'), ('37', 'Lungs', '40', '93', 'Airway irritation continues to subside as the lining of the respiratory tract returns to normal structure and mucus clearance stabilizes', 'Tashkin DP. Ann Am Thorac Soc. 2013.', '-89'), ('38', 'Lungs', '50', '94', 'Reports of coughing and phlegm production decrease further as small-airway obstruction continues to decline', 'Hancox RJ et al. Eur Respir J. 2015.', '29'), ('39', 'Lungs', '60', '96', 'Bronchitis-like symptoms typically resolve completely in cannabis-only smokers; mucociliary defenses function normally again', 'Hancox RJ et al. 2015; Tashkin DP 2013; Pletcher MJ et al. JAMA 2012; Taylor DR et al. Thorax 2002.', '27'), ('40', 'Lungs', '75', '97', 'Oxygen exchange efficiency improves; some individuals notice enhanced respiratory endurance with consistent abstinence', 'Pletcher MJ et al. JAMA 2012; Hancox RJ et al. 2015.', '103'), ('41', 'Lungs', '90', '100', 'Lung structure and cilia function approach full recovery; former cannabis-only smokers show no greater risk of chronic bronchitis than non-smokers', 'Hancox RJ et al. 2015; Tashkin DP 2013.', '56');